    <LocalizationProvider dateAdapter={AdapterDayjs}>
      <DemoContainer components={['StaticDateRangePicker']}>
        <ThemeProvider theme={theme}>
          <StaticDateRangePicker />
        </ThemeProvider>
      </DemoContainer>
    </LocalizationProvider>
  );
}

